from collections import Counter
def flank_fill(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    obj=[(r,c) for r in range(h) for c in range(w) if g[r][c]!=bg]
    # adjacency count to decide mode
    adj=sum(1 for r,c in obj for dr,dc in ((0,1),(1,0)) if 0<=r+dr<h and 0<=c+dc<w and g[r+dr][c+dc]!=bg)
    out=[row[:] for row in g]
    if adj>=len(obj)*0.3:  # frame mode
        for r in range(h):
            for c in range(w):
                if g[r][c]==bg:
                    if c>0 and c<w-1 and g[r][c-1]!=bg and g[r][c+1]!=bg: out[r][c]=2
                    elif r>0 and r<h-1 and g[r-1][c]!=bg and g[r+1][c]!=bg: out[r][c]=2
    else:
        rs=[r for r,_ in obj]; cs=[c for _,c in obj]
        for r in range(min(rs),max(rs)+1):
            for c in range(min(cs),max(cs)+1):
                if out[r][c]==bg: out[r][c]=2
    return out
